// CMS-managed content. The admin panel writes src/data/menu-panels.json; this
// module reads the latest file on every render. (Originally generated by
// scripts/extract-menu.mjs.)

import { loadLocalizedData } from "@/lib/data-files"
import { SITE_SCOPE, hrefVisibleInScope } from "@/lib/site-scope"
import { DEFAULT_LOCALE, type Locale } from "@/i18n/config"

export interface MenuImageCard {
  title: string
  href: string
  image: string | null
  description?: string | null
}

export interface MenuColumn {
  heading: string | null
  intro: string | null
  cards: MenuImageCard[]
  thumbnails: MenuImageCard[]
  links: { title: string; href: string }[]
}

export interface MenuPanel {
  label: string
  href: string
  columns: MenuColumn[]
}

interface MenuPanelsData {
  menuPanels: MenuPanel[]
  appPromotion: {
    desc: string
    qrCodeUrl: string
    appDownloadUrl: string
  }
}

export function getMenuPanels(locale: Locale = DEFAULT_LOCALE): MenuPanel[] {
  // The portal uses its own minimal header, not the storefront mega menu.
  if (SITE_SCOPE === "portal") return []
  return loadLocalizedData<MenuPanelsData>("menu-panels.json", locale).menuPanels.flatMap(
    (panel) => {
      // Drop panels that belong to the other catalogue before inspecting links.
      if (!hrefVisibleInScope(panel.href)) return []
      const columns = panel.columns
        .map((column) => ({
          ...column,
          cards: column.cards.filter((card) => hrefVisibleInScope(card.href)),
          thumbnails: column.thumbnails.filter((item) => hrefVisibleInScope(item.href)),
          links: column.links.filter((link) => hrefVisibleInScope(link.href)),
        }))
        .filter(
          (column) =>
            column.cards.length > 0 ||
            column.thumbnails.length > 0 ||
            column.links.length > 0 ||
            Boolean(column.heading || column.intro),
        )
      return columns.length > 0 ? [{ ...panel, columns }] : []
    },
  )
}

export function getAppPromotion(locale: Locale = DEFAULT_LOCALE): MenuPanelsData["appPromotion"] {
  return loadLocalizedData<MenuPanelsData>("menu-panels.json", locale).appPromotion
}
